-- =====================================================================================
--  Malica Office — File d'ingestion du corpus juridique tunisien
--
--  Ce fichier ne contient AUCUN texte de loi. Il contient la LISTE de ce qu'il faut lire,
--  vérifiée document par document : chaque URL a répondu, chaque langue a été mesurée sur
--  le fichier et non déduite du libellé du lien.
--
--  L'ORDRE COMPTE, et il n'est pas chronologique. La prescription fiscale de droit commun
--  borne ce qui est opposable : une note commune de 2004 a une valeur historique, pas
--  opérationnelle. Ingérer 686 notes n'est pas la priorité — ingérer les bonnes l'est.
--
--    priorite 1  éditions consolidées 2025-2026 des codes  -> c'est la loi applicable
--    priorite 2  lois de finances 2021-2026                -> ce qui amende cette loi
--    priorite 3  notes communes 2021-2026                  -> la doctrine encore opposable
--    priorite 4  notes communes antérieures à 2021         -> archive
--    priorite 5  lois de finances et codes antérieurs      -> archive
--
--  Le compte de 652 notes communes qui circule est un instantané d'août 2024. Le catalogue
--  en indexe 686 aujourd'hui, plus 2 publiées hors taxonomie : 688 documents réels.
--
--  Idempotent.
-- =====================================================================================

create table if not exists legal.ingestion_queue (
  id            uuid primary key default gen_random_uuid(),
  priorite      int  not null,
  type_document text not null,
  corpus        text not null,
  annee         int,
  titre         text not null,
  langue        text not null,
  url_fichier   text,
  url_fiche     text,
  pages         int,
  statut        text not null default 'a_faire'
                check (statut in ('a_faire','en_cours','ingere','echec','ignore')),
  sha256_source char(64),
  ingere_le     timestamptz,
  echec_motif   text
);

-- Clé naturelle : la fiche du portail identifie un document, pas son titre.
-- Deux notes peuvent partager un titre au caractère près et être deux documents distincts —
-- la version française et la version arabe de la NC 02/2025 en sont l'exemple, et l'une des
-- deux a un lien mort. Les confondre ferait disparaître la lacune.
create unique index if not exists ux_ingestion_queue_document
  on legal.ingestion_queue (coalesce(url_fiche, url_fichier, titre));

comment on table legal.ingestion_queue is
  'File de travail du pipeline d''ingestion. Un document sans url_fichier est catalogué mais '
  'non récupérable : il reste visible, en statut a_faire, pour que la lacune ne disparaisse pas.';

insert into legal.ingestion_queue
  (priorite, type_document, corpus, annee, titre, langue, url_fichier, url_fiche, pages)
select v.p, v.typ, v.corpus, v.annee, v.titre, v.langue, v.url, v.urlp, v.pages
from (values
  (1,'CODE_CONSOLIDE','CFL',2026,'CFL édition 2026','fr','https://jibaya.tn/wp-content/uploads/2026/06/Code-de-la-Fiscalite-Locale-2026.pdf','https://jibaya.tn/docs/code-de-la-fiscalite-locale-2026/',126),
